async function touchLongPress(page,locator){
  await locator.scrollIntoViewIfNeeded();
  const box=await locator.boundingBox();assert.ok(box,"touch target unavailable");
  const point={x:Math.round(box.x+box.width/2),y:Math.round(box.y+box.height/2)};
  const hit=await locator.evaluate((node,point)=>{const target=document.elementFromPoint(point.x,point.y);return {inViewport:point.x>=0&&point.x<window.innerWidth&&point.y>=0&&point.y<window.innerHeight,sameTarget:Boolean(target&&(target===node||node.contains(target)))};},point);
  assert.equal(hit.inViewport,true,"touch target center is inside the viewport");
  assert.equal(hit.sameTarget,true,"touch target center resolves to the current Show hint button");
  const session=await page.context().newCDPSession(page);
  try{
    await session.send("Input.dispatchTouchEvent",{type:"touchStart",touchPoints:[{...point,id:1}]});
    await page.clock.fastForward(499);assert.equal(await page.getByRole("region",{name:"Stored hints"}).count(),0,"touch stored-hints before 500ms");
    await page.clock.fastForward(1);await session.send("Input.dispatchTouchEvent",{type:"touchEnd",touchPoints:[]});
  }finally{await session.detach();}
}
