      child.once("error",fatal);origin=`http://127.0.0.1:${port}`;
      let ready=false;for(let tick=0;tick<150&&!ready;tick++){if(primary||child.exitCode!==null)break;try{const response=await fetch(origin);const body=await response.text();ready=response.status===200&&body.includes("Safe Cat 07 Harness");}catch{}if(!ready)await readinessDelay(100);}
      if(ready)break;
